struct StateHash {
    size_t operator()(const State& s) const {
        uint64_t x = s.remaining;
        x ^= x >> 30;
        x *= 0xbf58476d1ce4e5b9ULL;
        x ^= x >> 27;
        x *= 0x94d049bb133111ebULL;
